		}

		private static List<String> signaturesOf(List<Method> methods) {
			// @formatter:off
			return methods.stream()
					.map(m -> String.format("%s(%s)", m.getName(), ClassUtils.nullSafeToString(m.getParameterTypes())))
					.collect(toList());
			// @formatter:on
		}

