##########################
package org.junit.platform.commons.util;

import static org.assertj.core.api.Assertions.assertThat;
import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.platform.commons.util.ReflectionUtils.HierarchyTraversalMode.TOP_DOWN;
import static org.junit.platform.commons.util.ReflectionUtils.findMethods;

import java.lang.reflect.Method;

public class ReflectionUtilsTestUtils {

    private static final Predicate<Method> methodContains1 = method -> method.getName().contains("1");
    private static final Predicate<Method> methodContains2 = method -> method.getName().contains("2");
    private static final Predicate<Method> methodContains4 = method -> method.getName().contains("4");
    private static final Predicate<Method> methodContains5 = method -> method.getName().contains("5");

    public static void assertFindMethodsWithShadowingUsingHierarchyDownMode(Class<?> testClass) throws Exception {
        assertThat(findMethods(testClass, methodContains1, TOP_DOWN))
                .containsExactly(testClass.getMethod("method1", String.class));

        assertThat(findMethods(testClass, methodContains2, TOP_DOWN))
                .containsExactly(testClass.getMethod("method2", int.class, int.class),
                    testClass.getSuperclass().getMethod("method2", int.class, int.class, int.class));

        assertThat(findMethods(testClass, methodContains4, TOP_DOWN))
                .containsExactly(testClass.getMethod("method4", boolean.class));

        assertThat(findMethods(testClass, methodContains5, TOP_DOWN))
                .containsExactly(testClass.getSuperclass().getMethod("method5", String.class),
                    testClass.getMethod("method5", Long.class));

        var methods = findMethods(testClass, method -> true, TOP_DOWN);
        assertEquals(6, methods.size());
        assertEquals(testClass.getMethod("method2", int.class, int.class), methods.get(0));
        assertThat(methods.subList(1, 3)).containsOnly(
            testClass.getSuperclass().getMethod("method2", int.class, int.class, int.class),
            testClass.getSuperclass().getMethod("method5", String.class));
        assertThat(methods.subList(3, 6)).containsOnly(testClass.getMethod("method4", boolean.class),
            testClass.getMethod("method1", String.class),
            testClass.getMethod("method5", Long.class));
    }
}
