public static void assertFindMethodsTopDown(Class<?> clazz, Predicate<Method> predicate, Class<?>... expectedMethods) throws Exception {
    assertThat(findMethods(clazz, predicate, TOP_DOWN))
        .containsExactly(Arrays.stream(expectedMethods)
            .map(c -> {
                try {
                    return c.getMethod(predicate.toString().contains("other") ? 
                        expectedMethods[0] == c ? "otherMethod1" : 
                        expectedMethods[1] == c ? "otherMethod2" : "otherMethod3" :
                        expectedMethods[0] == c ? "method1" : 
                        expectedMethods[1] == c ? "method2" : 
                        expectedMethods[2] == c ? "method3" : "method4");
                } catch (Exception e) {
                    throw new RuntimeException(e);
                }
            })
            .toArray(Method[]::new));
}
