void findMethodsUsingHierarchyDownMode() throws Exception {
    assertFindMethodsTopDown(ChildClass.class, method -> method.getName().contains("method"), 
        GrandparentClass.class, GrandparentInterface.class, ParentClass.class, ChildClass.class);

    assertFindMethodsTopDown(ChildClass.class, method -> method.getName().contains("other"), 
        GrandparentClass.class, ParentClass.class, ChildClass.class);

    assertThat(findMethods(ChildClass.class, method -> method.getName().equals("method2"), TOP_DOWN))
        .containsExactly(ParentClass.class.getMethod("method2"));

    assertThat(findMethods(ChildClass.class, method -> method.getName().equals("wrongName"), TOP_DOWN)).isEmpty();

    assertFindMethodsTopDown(ParentClass.class, method -> method.getName().contains("method"), 
        GrandparentClass.class, GrandparentInterface.class, ParentClass.class);
}
