	@Test
	void findMethodByParameterTypesInGenericInterfaceViaParameterizedSubclass() {
		Class<?> clazz = InterfaceWithGenericDefaultMethodImpl.class;
		var method = findMethod(clazz, "foo", Long.class);
		assertThat(method).isNotEmpty();
