									() -> assertTrue( //
										declaredMethods.stream().anyMatch(it -> //
										it.getName().equals(m.getName()) //
												&& it.getReturnType().equals(m.getReturnType()) //
												&& Arrays.equals(it.getParameterTypes(), m.getParameterTypes()) //
										))) //
								) //
					) //
				));
	}

	private List<Class<?>> findExtensionApis() {
