private List<Class<?>> findAllExtensionApis() {
    return ReflectionUtils.findAllClassesInPackage(Extension.class.getPackage().getName(),
        this::isExtensionApi, name -> true);
}

private List<Method> findExpectedMethods(List<Class<?>> extensionApis) {
    return extensionApis.stream()
            .map(Class::getDeclaredMethods)
            .flatMap(Arrays::stream)
            .filter(not(Method::isSynthetic))
            .filter(not(where(Method::getModifiers, Modifier::isStatic)))
            .collect(toList());
}

private List<String> getMethodSignatures(List<Method> methods) {
    return methods.stream()
            .map(this::methodSignature)
            .sorted()
            .collect(toList());
}

private List<String> getMethodNames(List<Method> methods) {
    return methods.stream()
            .map(Method::getName)
            .distinct()
            .sorted()
            .collect(toList());
}

private Object createDynamicProxy(List<Class<?>> extensionApis) {
    return Proxy.newProxyInstance(getClass().getClassLoader(),
        extensionApis.toArray(Class[]::new), (proxy, method, args) -> null);
}

private List<Method> findActualMethods(Object proxy) {
    return Arrays.stream(proxy.getClass().getDeclaredMethods())
            .filter(ReflectionUtils::isNotStatic)
            .collect(toList());
}

private void removeObjectMethods(List<String> signatures, List<String> names) {
    signatures.remove("equals(Object)");
    signatures.remove("hashCode()");
    signatures.remove("toString()");
    names.remove("equals");
    names.remove("hashCode");
    names.remove("toString");
}

