		}

		@Override
		public void handleBeforeEachMethodExecutionException(ExtensionContext context, Throwable throwable) {
			callCounter.incrementBeforeEachCalls();
			handlerCalls.add("SwallowExceptionBeforeEach");
			// Do not rethrow
