package org.junit.platform.commons.support;

import org.junit.jupiter.api.function.Executable;
import org.junit.platform.commons.PreconditionViolationException;

import static org.junit.jupiter.api.Assertions.assertThrows;

public final class PreconditionAssertions {

    private PreconditionAssertions() {
        /* no-op */
    }

    public static void assertViolatesPrecondition(Executable precondition) {
        assertThrows(PreconditionViolationException.class, precondition);
    }
}
