// Add this method to ClassUtils class
public static String getFullyQualifiedMethodName(Class<?> clazz, String methodName, Class<?>... parameterTypes) {
    Preconditions.notNull(clazz, "Class must not be null");
    Preconditions.notBlank(methodName, "Method name must not be null or blank");

    String parameterTypeNames = (parameterTypes != null) 
        ? stream(parameterTypes).map(Class::getName).collect(joining(", "))
        : "";

    return String.format("%s#%s(%s)", clazz.getName(), methodName, parameterTypeNames);
}
